// 2026-10-12 (wavetell), HIS ANSWER 10 a: a spawn telegraph before a wave. A wave no longer appears out of nothing: when the director
// has picked the ground, a red drop-in flare goes up there with a rising charge sound and WAVE INCOMING, and the pack lands at the
// flare WAVE_TELL seconds later. The flare is drawn above the dark and the fog (a burning core, a pulsing ring on the ground and a
// beam), so you see where they will land and can set up or move. Player 2 sees the same flare (the wtell word). The pack, its size,
// its kinds and its clock are unchanged, and the flare draws nothing from any stream.
var WAVE_TELL=2.5;
function waveTellFx(x,y,send){
  if(!G||G.sim) return;
  if(!Array.isArray(G.wtells)) G.wtells=[];
  G.wtells.push({x:x,y:y,t0:+G.t||0,life:WAVE_TELL+0.6});
  try{ sfx('charge',x,y); }catch(_ws){}
  flash(x,y,320,'#ff4a3a',.6);
  try{ say('WAVE INCOMING','warn'); }catch(_wy){}
  if(send) try{ netThrSend('wtell',x,y); }catch(_wn){}
}
function waveTellDraw(Z,ox,oy){
  var i, w, a, k, pu, r, gr, t=+G.t||0;
  for(i=G.wtells.length-1;i>=0;i--) if(t-G.wtells[i].t0>G.wtells[i].life||t<G.wtells[i].t0) G.wtells.splice(i,1);
  if(!G.wtells.length) return;
  wc.save(); wc.scale(Z,Z); wc.translate(-ox,-oy);
  wc.globalCompositeOperation='lighter';
  for(i=0;i<G.wtells.length;i++){
    w=G.wtells[i]; a=t-w.t0; k=Math.max(0,Math.min(1,(w.life-a)/0.6)); pu=0.5+0.5*Math.sin(a*9);
    gr=wc.createLinearGradient(w.x,w.y-260,w.x,w.y);
    gr.addColorStop(0,'rgba(255,60,40,0)'); gr.addColorStop(1,'rgba(255,90,60,'+(0.42*k).toFixed(3)+')');
    wc.fillStyle=gr; wc.fillRect(w.x-7,w.y-260,14,260);
    for(r=0;r<2;r++){
      wc.strokeStyle='rgba(255,80,60,'+((0.55-0.25*r)*k*(0.6+0.4*pu)).toFixed(3)+')'; wc.lineWidth=3-r;
      wc.beginPath(); wc.arc(w.x,w.y,60+r*28+12*((a*1.6+r*0.5)%1),0,6.2832); wc.stroke();
    }
    gr=wc.createRadialGradient(w.x,w.y-4,0,w.x,w.y-4,34);
    gr.addColorStop(0,'rgba(255,240,210,'+(0.95*k).toFixed(3)+')'); gr.addColorStop(0.35,'rgba(255,90,50,'+(0.65*k).toFixed(3)+')'); gr.addColorStop(1,'rgba(255,40,30,0)');
    wc.fillStyle=gr; wc.beginPath(); wc.arc(w.x,w.y-4,34*(0.85+0.3*pu),0,6.2832); wc.fill();
  }
  wc.restore();
}
