{v:'VER',what:'his answer 10 a: a wave is telegraphed: a drop-in flare and WAVE INCOMING first, the pack lands at the flare 2.5 s later',
 run:function(){
   var bad=[], g, i, n0, lines=[], rs=say, own=false, c, made, d, tell=false;
   function waves(){ var k=0, j; for(j=0;j<g.ents.length;j++) if(g.ents[j]&&g.ents[j].arcWave) k++; return k; }
   try{
     __topClear(); __runPrep();
     if(typeof arcadeDeploy!=='function'||typeof arcadeWaveTick!=='function'||typeof ARCADE!=='object') return 'no arcade waves in this build';
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); keys={};
     say=function(m){ lines.push(String(m)); }; own=true;
     ARCADE.mine=8000; ARCADE.mate=0; ARCADE.holdT=0;
     g.ents=g.ents.filter(function(q){ return !(q&&!q.neutral&&q.kind!=='peddler'&&q.kind!=='stray'&&(q.kind!=='raider'||q.hostile)&&dist(q,g.player)<1500); });
     for(i=0;i<10&&!g.wtell&&!waves();i++){ ARCADE.waveT=999; arcadeWaveTick(0.05); }
     if(waves()) bad.push('a wave landed with no flare first');
     if(!g.wtell) return bad.length?bad.join('; '):'SKIP: no wave ground was found';
     c={x:g.wtell.x,y:g.wtell.y};
     if(!(Array.isArray(g.wtells)&&g.wtells.length)) bad.push('no flare is drawn');
     for(i=0;i<lines.length;i++) if(lines[i]==='WAVE INCOMING') tell=true;
     if(!tell) bad.push('no WAVE INCOMING callout');
     n0=g.ents.length;
     arcadeWaveTick(1); arcadeWaveTick(1);
     if(g.ents.length!==n0) bad.push('the pack landed after 2 s, before the flare burned down');
     arcadeWaveTick(0.6);
     made=waves();
     if(!made) bad.push('no pack after the flare burned down');
     for(i=0;i<g.ents.length;i++) if(g.ents[i]&&g.ents[i].arcWave){ d=dist(g.ents[i],c); if(d>110) bad.push('a wave body landed '+Math.round(d)+' from the flare'); }
     if(g.wtell) bad.push('the flare is still pending after the pack');
     if(!(ARCADE.waveN>0)) bad.push('the wave was not counted');
     try{ __frame(0.016); }catch(fx){ bad.push('the frame with a flare threw: '+(fx&&fx.message||fx)); }
   }catch(x){ bad.push('threw: '+(x&&x.message||x)); }
   finally{
     try{ if(own) say=rs; }catch(_s){}
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ if(typeof ARCADE==='object'){ ARCADE.over=null; ARCADE.mine=0; ARCADE.mate=0; ARCADE.pot=0; ARCADE.holdT=0; ARCADE.waveT=0; } }catch(_m){}
     keys={};
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
